// 글꾸 마트의 「틈 템플릿」(받기 JSON)과 미리보기 HTML 을 만들어요. 받은 사람의 테마는 log-copy-presets.js drawTemplate 로 그 자리에 부품을 끼워요.
// 틀 하나 = 색 묶음(MART_HALLOWEEN_COLORS) + 모양 조각(MART_HALLOWEEN_SHAPES · (k, p, ui) → HTML · p 는 head · body · info · tail 만) + 데이터 한 줄(MART_HALLOWEEN_FRAMES).
// 역할 색 이름 · 조각 상자(at · lane · dot · star · bat · al …)는 src/log-copy-concept-kit.js 를 봐요.
import { tag } from '../../src/log-copy-render.js';
import { box, font, hide, deco, at, lane, dot, star, bat, al, WHITE, STAR, BAT, centerAt, gap10, wrapOuter, svgDoc, svgUrl, art } from '../../src/log-copy-concept-kit.js';
import { mark } from '../../src/log-copy-render.js';
// 1.0.1 「틀이 가진 부품이 실제로 움직이는 대로 움직이고, 만질 수 있을 것 같은 부분을 누르면 반응」(덧붙인 이모지 없음)
//   live(조각, { anim, origin, vars, egg }): 조각 html 의 첫 태그에 움직임(src/log-copy-motion.js 공용 키프레임) · 축 · 거리 변수 · 누르면 반응(data-bl-egg)을 더해요.
//   원칙: 돌 · 땅 · 건물 · 큰 몸통은 그대로 · 매달린 것은 흔들 · 날개 있는 건 날기 · 액체는 보글 · 빛은 숨쉬기 · 깜박 · 천 · 리본 끝은 살랑 · 떠 있는 몸은 통째로 둥실.
const live = (html, { anim = '', origin = '', vars = '', egg = '' } = {}) => {
    let out = html.replace(/ style="([^"]*)"/, (_, st) => ` style="${st}${origin ? `;transform-origin:${origin}` : ''}${vars ? `;${vars}` : ''}${anim ? `;animation:${anim}` : ''}"`);
    if (egg) out = mark(out, `data-bl-egg="${egg}"`);
    return out;
};
// 모양 면 칸(머리 · 메시지 · 정보 · 꼬리): top 은 칸 안 맨 위 장식 줄(얼굴 · 창문 …) — 글 없는 줄이라 움직이는 부품을 둬도 글자와 안 겹쳐요
const faceCard = (k, style, p, top = '') => tag('div', { ...box, position: 'relative', 'background-color': k.face, color: k.faceText, ...style }, top + p.head + gap10 + p.body + p.info + tag('div', { 'margin-top': '10px' }, p.tail));

